insert into public.safety_checklist_categories (id, code, label, active, "position", created_at) select id, code, label, active, "position", created_at from jsonb_populate_recordset(null::public.safety_checklist_categories, '[{"id": "21666075-2e10-4a7b-9f9b-c326f26c5311", "code": "I", "label": "Egna punkter / objektsspecifika risker", "active": true, "position": 9, "created_at": "2026-09-24T12:55:55.030711+00:00"}, {"id": "2673845c-e32d-4673-b8c2-04dfb94ec960", "code": "E", "label": "Maskiner, slangar, el och fordon", "active": true, "position": 5, "created_at": "2026-09-24T12:55:55.030711+00:00"}, {"id": "46859743-4707-45cb-8159-42dcdfac5abd", "code": "H", "label": "Organisation, samordning och OSA på plats", "active": true, "position": 8, "created_at": "2026-09-24T12:55:55.030711+00:00"}, {"id": "4e598905-71f1-40e1-bfd8-b7eb0759db1f", "code": "A", "label": "Tillträde, ordning och allmän säkerhet", "active": true, "position": 1, "created_at": "2026-09-24T12:55:55.030711+00:00"}, {"id": "8a99582b-080c-4a6e-ad67-ef157fb36fb1", "code": "B", "label": "Fallrisk och arbete på höjd", "active": true, "position": 2, "created_at": "2026-09-24T12:55:55.030711+00:00"}, {"id": "94c4bad6-4ddf-475e-a51a-d382a06888af", "code": "G", "label": "Personlig skyddsutrustning och klädsel", "active": true, "position": 7, "created_at": "2026-09-24T12:55:55.030711+00:00"}, {"id": "ba08c76f-d983-4444-b516-47bef5c6f6bf", "code": "F", "label": "Material och avfall", "active": true, "position": 6, "created_at": "2026-09-24T12:55:55.030711+00:00"}, {"id": "be770e8d-1ece-42cd-a026-017087f09f24", "code": "C", "label": "Damm, kvarts och luft (särskilt lösull/cellulosa/sågning)", "active": true, "position": 3, "created_at": "2026-09-24T12:55:55.030711+00:00"}, {"id": "f1c8f2b3-f61d-4301-b260-feb8d9eb4ed3", "code": "D", "label": "Ergonomi, lyft och arbetsställningar", "active": true, "position": 4, "created_at": "2026-09-24T12:55:55.030711+00:00"}]'::jsonb);
insert into public.safety_checklist_items (id, text, active, number, "position", created_at, category_id) select id, text, active, number, "position", created_at, category_id from jsonb_populate_recordset(null::public.safety_checklist_items, E'[{"id": "1286dbdf-643f-4617-aad0-038a40d1149e", "text": "Gångvägar, transportvägar och uppställningsytor är fria från material, slangar och skräp?", "active": true, "number": 1, "position": 1, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "4e598905-71f1-40e1-bfd8-b7eb0759db1f"}, {"id": "187fcbbe-cc59-4814-9f28-bba08f8aea95", "text": "Fallskyddssele används när räcke saknas, och fästpunkt är godkänd (inte i stege)?", "active": true, "number": 4, "position": 1, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "8a99582b-080c-4a6e-ad67-ef157fb36fb1"}, {"id": "1b3795b1-65ac-47e6-a807-ef87286e8ef0", "text": "Paus och återhämtning möjligt vid kyla, värme eller hög arbetsbelastning?", "active": true, "number": 8, "position": 2, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "f1c8f2b3-f61d-4301-b260-feb8d9eb4ed3"}, {"id": "1d795903-771b-4268-9298-a036fdffe60f", "text": "Ensamarbete undviks eller har avstämningsrutin (särskilt vind/krypgrund)?", "active": true, "number": 41, "position": 2, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "46859743-4707-45cb-8159-42dcdfac5abd"}, {"id": "1ee66347-99bd-440c-a09d-5d67f31c4fc5", "text": "Avfall (plast, spill, dammfilter) samlas och lämnas enligt rutin?", "active": true, "number": 12, "position": 1, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "ba08c76f-d983-4444-b516-47bef5c6f6bf"}, {"id": "215ccbc3-b768-4f15-9e62-4328dbaf99bd", "text": "Kläder rena från damm vid raster/hemfärd (ta inte med kvartsdamm hem)?", "active": true, "number": 37, "position": 4, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "94c4bad6-4ddf-475e-a51a-d382a06888af"}, {"id": "27cb2a4e-58d7-4320-a1a9-e0042c2027dc", "text": "Alla på platsen vet vem som är arbetsledare och hur man anmäler risk/tillbud?", "active": true, "number": 38, "position": 1, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "46859743-4707-45cb-8159-42dcdfac5abd"}, {"id": "45d0c64f-9a4f-454f-95c2-b60bce7f6f85", "text": "Handskar anpassade till moment (skär samt kyla)?", "active": true, "number": 35, "position": 2, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "94c4bad6-4ddf-475e-a51a-d382a06888af"}, {"id": "4a6cf04f-a303-4ab3-993c-269bb2e9e52a", "text": "Elverktyg och sladdar hela, jordade/skyddade, inte i vatten eller gångväg?", "active": true, "number": 10, "position": 2, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "2673845c-e32d-4673-b8c2-04dfb94ec960"}, {"id": "66f42b5a-228c-4227-96e0-f9d38040afd4", "text": "Blåsmaskin, slangar hela, rätt kopplade?", "active": true, "number": 9, "position": 1, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "2673845c-e32d-4673-b8c2-04dfb94ec960"}, {"id": "6df083f6-7925-4704-9059-803fdb3929d5", "text": "Hjälm, skyddsskor, varsel, skyddsglasögon används där det krävs på bygget?", "active": true, "number": 34, "position": 1, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "94c4bad6-4ddf-475e-a51a-d382a06888af"}, {"id": "6ed2d149-6d7c-4d7e-a309-b74e8ef5aa95", "text": "Daglig tillsyn av fordon/maskin gjord? Synliga fel anmälda?", "active": true, "number": 11, "position": 3, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "2673845c-e32d-4673-b8c2-04dfb94ec960"}, {"id": "77f0414e-5289-487a-a0f9-86abe60dcdca", "text": "Andningsskydd och hörselskydd används när risken finns, och underhålls?", "active": true, "number": 36, "position": 3, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "94c4bad6-4ddf-475e-a51a-d382a06888af"}, {"id": "7fa39d73-a5e1-4e35-ab63-5e77e9415421", "text": "Arbete över axelhöjd / i knä begränsas och varvas med andra moment?", "active": true, "number": 7, "position": 1, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "f1c8f2b3-f61d-4301-b260-feb8d9eb4ed3"}, {"id": "8638aaf2-35fa-48eb-91fe-844aab2b2bfc", "text": "Utrymningsvägar kända och fria? Samlingsplats känd?", "active": true, "number": 2, "position": 2, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "4e598905-71f1-40e1-bfd8-b7eb0759db1f"}, {"id": "8e35e817-c2ad-4c39-be9d-60f6f2fba1fe", "text": "Tillbud och nästan-olyckor från senaste tiden är kända och åtgärdade?", "active": true, "number": 43, "position": 4, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "46859743-4707-45cb-8159-42dcdfac5abd"}, {"id": "9a5f7289-c6ad-43a5-bcf8-9c60334dff97", "text": "Stegar hela, rätt lutning, förankrade och används bara för kort, enkelt arbete?", "active": true, "number": 5, "position": 2, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "8a99582b-080c-4a6e-ad67-ef157fb36fb1"}, {"id": "c7730a31-0b54-49b6-859e-ec4b5a88b7c8", "text": "Första hjälpen-väska och ögondusch/spolning tillgänglig och komplett?", "active": true, "number": 3, "position": 3, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "4e598905-71f1-40e1-bfd8-b7eb0759db1f"}, {"id": "c85194bd-ce02-41ac-8d27-07b132e726e9", "text": "Arbetsbelastning och tidplan tillåter säkert arbete – inte bara \\"köra på\\"?", "active": true, "number": 42, "position": 3, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "46859743-4707-45cb-8159-42dcdfac5abd"}, {"id": "e023f840-4b87-4fb4-b6e4-1b74e6141a8b", "text": "Andningsskydd (rätt filter, rätt modell, utprovat) används när damm inte kan elimineras?", "active": true, "number": 6, "position": 1, "created_at": "2026-09-24T12:55:55.030711+00:00", "category_id": "be770e8d-1ece-42cd-a026-017087f09f24"}]'::jsonb);
